/* ============================================================
   TORNEO — Tampa Bay Super Cup · complemento del admin.
   Se activa agregando al final de admin.html, después de Liga.js:
     <script src="Torneo.js"></script>
   NO toca la liga: los equipos del torneo viven aquí y
   los goles de torneo NO se suman a la tabla de temporada
   (el tipo se guarda en config.tipo; ver acumularStats).
   Partidos U13 del torneo: 2x35 min, 5 min de descanso.
   ============================================================ */
const TORNEO_NOMBRE = 'Tampa Bay Super Cup \u00b7 U13';
const TORNEO_EQUIPOS = [
  { n: "AC Florida West", logo: "data:image/webp;base64," },
  { n: "Team Boca", logo: "data:image/webp;base64," },
  { n: "Wilmington Hammerheads", logo: "data:image/webp;base64," },
];

window.addEventListener('DOMContentLoaded', ()=>{
  const selT = $('selTipo');
  const selB = $('selEquipoB');
  const titulo = $('titulo');
  if(!selT || !selB) return;

  /* 1) Opción Torneo en el selector de tipo */
  const op = document.createElement('option');
  op.value = 'torneo';
  op.textContent = 'Torneo \u00b7 Tampa Bay Super Cup';
  selT.appendChild(op);

  /* 2) Menú de Equipo B según el tipo (liga o torneo) */
  let listaB = (typeof LIGA_EQUIPOS !== 'undefined') ? LIGA_EQUIPOS : [];
  function cargarEquiposB(){
    const esTorneo = selT.value === 'torneo';
    listaB = esTorneo ? TORNEO_EQUIPOS : LIGA_EQUIPOS;
    selB.innerHTML = '<option value="">\u2014 Elegir equipo ' + (esTorneo ? 'del torneo' : 'de la liga') + ' \u2014</option>' +
      listaB.map((e,i)=>'<option value="'+i+'">'+e.n+'</option>').join('') +
      '<option value="manual">\u270F\uFE0F Otro equipo (escribir manual)</option>';
    const nombreB = $('nombreB');
    if(nombreB){ nombreB.value = ''; nombreB.disabled = false; }
    logoBData = '';
    const prev = $('logoB-prev'); if(prev) prev.style.display = 'none';
  }
  selB.onchange = ()=>{
    const v = selB.value;
    const nombreB = $('nombreB');
    if(v === '' || v === 'manual'){
      if(nombreB){ nombreB.value = ''; nombreB.disabled = false; }
      logoBData = '';
      const prev = $('logoB-prev'); if(prev) prev.style.display = 'none';
      if(v === 'manual' && nombreB) nombreB.focus();
    }else{
      const e = listaB[+v];
      if(nombreB){ nombreB.value = e.n; nombreB.disabled = true; }
      logoBData = e.logo;
      const prev = $('logoB-prev');
      if(prev){ prev.src = e.logo; prev.style.display = 'block'; }
    }
  };

  /* 3) Título según el tipo (respeta la lógica de liga) */
  const aplicarLiga = selT.onchange;
  selT.onchange = ()=>{
    if(selT.value === 'torneo'){
      if(titulo){ titulo.value = TORNEO_NOMBRE; titulo.disabled = true; }
    }else{
      if(titulo && titulo.value === TORNEO_NOMBRE) titulo.value = '';
      if(typeof aplicarLiga === 'function') aplicarLiga();
    }
    cargarEquiposB();
  };
});
